-- 108: Original BrillaPrep 4BI1 beta questions, part 2.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_021', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which change can be inherited by offspring?', 'multiple_choice', '["A. A mutation in a gamete-producing cell","B. A scar on the skin","C. Increased muscle from exercise","D. A suntan"]', 'A', 'Only genetic changes that enter gametes can be transmitted through fertilisation to offspring. Therefore the correct answer is A: A mutation in a gamete-producing cell.', 'hard', 1, 1, 90, 'st_edx_4bi1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_022', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What is the role of the placenta?', 'multiple_choice', '["A. It mixes the two blood supplies directly","B. It permits exchange between maternal and fetal blood supplies","C. It produces sperm cells","D. It digests food for the mother"]', 'B', 'The placenta provides a large exchange surface while keeping maternal and fetal blood separate. Therefore the correct answer is B: It permits exchange between maternal and fetal blood supplies.', 'easy', 2, 2, 90, 'st_edx_4bi1_3', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_023', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why does sexual reproduction increase variation?', 'multiple_choice', '["A. Every offspring is a clone","B. Mitosis creates identical alleles","C. Gametes from two parents combine different alleles","D. Only one parent contributes DNA"]', 'C', 'Meiosis and random fertilisation produce new allele combinations in each sexually produced offspring. Therefore the correct answer is C: Gametes from two parents combine different alleles.', 'medium', 1, 1, 90, 'st_edx_4bi1_3', 'Explain', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_024', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which statement describes a dominant allele?', 'multiple_choice', '["A. It is always the most common allele","B. It can appear only in females","C. It is expressed only with two copies","D. It affects the phenotype when one copy is present"]', 'D', 'In a heterozygote, one dominant allele is sufficient to influence the observed characteristic. Therefore the correct answer is D: It affects the phenotype when one copy is present.', 'hard', 2, 2, 90, 'st_edx_4bi1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_025', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What is the main purpose of random quadrat sampling?', 'multiple_choice', '["A. To obtain an unbiased estimate of abundance","B. To count only the largest organisms","C. To eliminate natural variation","D. To measure air pressure"]', 'A', 'Random placement reduces selection bias, making the sample more representative of the habitat. Therefore the correct answer is A: To obtain an unbiased estimate of abundance.', 'easy', 3, 3, 90, 'st_edx_4bi1_4', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_026', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which organisms begin most food chains by capturing light energy?', 'multiple_choice', '["A. Decomposers","B. Producers","C. Secondary consumers","D. Parasites"]', 'B', 'Photosynthetic producers convert light energy into chemical energy available to other trophic levels. Therefore the correct answer is B: Producers.', 'medium', 2, 2, 90, 'st_edx_4bi1_4', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_027', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why is less energy available at each higher trophic level?', 'multiple_choice', '["A. Energy is created by predators","B. All biomass is fully digested","C. Energy is lost in respiration, waste and uneaten material","D. Consumers stop respiring"]', 'C', 'Only part of consumed biomass becomes new biomass; much energy is transferred to the surroundings. Therefore the correct answer is C: Energy is lost in respiration, waste and uneaten material.', 'hard', 1, 1, 90, 'st_edx_4bi1_4', 'Explain', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_028', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which process returns carbon dioxide to the atmosphere?', 'multiple_choice', '["A. Photosynthesis","B. Nitrification","C. Protein synthesis","D. Respiration"]', 'D', 'Respiration oxidises organic compounds and releases carbon dioxide as a metabolic product. Therefore the correct answer is D: Respiration.', 'easy', 2, 2, 90, 'st_edx_4bi1_4', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_029', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What is eutrophication commonly caused by?', 'multiple_choice', '["A. Nitrate or phosphate enrichment of water","B. Removal of all mineral ions","C. Reduced light from an eclipse","D. Increased dissolved oxygen"]', 'A', 'Nutrient enrichment drives algal growth, followed by decomposition that lowers dissolved oxygen. Therefore the correct answer is A: Nitrate or phosphate enrichment of water.', 'medium', 1, 1, 90, 'st_edx_4bi1_4', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_030', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which relationship benefits both species?', 'multiple_choice', '["A. Predation","B. Mutualism","C. Parasitism","D. Competition"]', 'B', 'In mutualism, each interacting species gains a benefit that can improve survival or reproduction. Therefore the correct answer is B: Mutualism.', 'hard', 3, 3, 90, 'st_edx_4bi1_4', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_031', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why can deforestation increase atmospheric carbon dioxide?', 'multiple_choice', '["A. Trees begin absorbing more carbon","B. Respiration stops everywhere","C. Less photosynthesis occurs and stored carbon may be released","D. Fossil fuels form immediately"]', 'C', 'Removing trees reduces carbon fixation, while burning or decay transfers stored carbon to the air. Therefore the correct answer is C: Less photosynthesis occurs and stored carbon may be released.', 'easy', 1, 1, 90, 'st_edx_4bi1_4', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_032', 'topic_edx_4bi1_4', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What does a population consist of?', 'multiple_choice', '["A. All species on Earth","B. Only producers in a habitat","C. All non-living factors","D. Members of one species living in the same area"]', 'D', 'A population is defined by a single species, a shared location and the same time period. Therefore the correct answer is D: Members of one species living in the same area.', 'medium', 2, 2, 90, 'st_edx_4bi1_4', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_033', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why are microorganisms used in industrial fermenters?', 'multiple_choice', '["A. They convert substrates into useful products rapidly","B. They remove every need for sterile conditions","C. They cannot mutate","D. They always photosynthesise"]', 'A', 'Controlled microbial metabolism can produce enzymes, foods, medicines and other useful substances efficiently. Therefore the correct answer is A: They convert substrates into useful products rapidly.', 'hard', 1, 1, 90, 'st_edx_4bi1_5', 'Explain', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_034', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why must a fermenter be kept sterile?', 'multiple_choice', '["A. To remove the production organism","B. To prevent contamination and competition from unwanted microbes","C. To stop all enzyme activity","D. To increase mutation rate"]', 'B', 'Sterility protects product purity and prevents contaminants using nutrients or producing harmful substances. Therefore the correct answer is B: To prevent contamination and competition from unwanted microbes.', 'easy', 2, 2, 90, 'st_edx_4bi1_5', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_035', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What is selective breeding?', 'multiple_choice', '["A. Changing DNA directly in a laboratory","B. Allowing only random mating","C. Choosing parents with desired phenotypes to reproduce","D. Cloning every wild organism"]', 'C', 'Repeatedly breeding selected parents increases the frequency of alleles associated with desired traits. Therefore the correct answer is C: Choosing parents with desired phenotypes to reproduce.', 'medium', 3, 3, 90, 'st_edx_4bi1_5', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_036', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which is a potential benefit of genetic modification in crops?', 'multiple_choice', '["A. Guaranteeing zero ecological impact","B. Removing all genetic variation","C. Preventing every plant disease","D. Introducing a specific pest-resistance gene"]', 'D', 'Genetic engineering can add a defined characteristic, although benefits and risks still require evaluation. Therefore the correct answer is D: Introducing a specific pest-resistance gene.', 'hard', 2, 2, 90, 'st_edx_4bi1_5', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_037', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why is mycoprotein production efficient?', 'multiple_choice', '["A. Fungi can grow rapidly on relatively little land","B. It requires mature cattle","C. It uses no nutrients","D. It produces only cellulose"]', 'A', 'Fungal biomass grows in fermenters and can provide protein with lower land demand than livestock. Therefore the correct answer is A: Fungi can grow rapidly on relatively little land.', 'easy', 1, 1, 90, 'st_edx_4bi1_5', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_038', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What do pectinase enzymes help produce?', 'multiple_choice', '["A. Solid plastic polymers","B. Clearer fruit juice with higher yield","C. Atmospheric nitrogen","D. Human insulin directly"]', 'B', 'Pectinase breaks down pectin in plant cell walls, helping release and clarify fruit juice. Therefore the correct answer is B: Clearer fruit juice with higher yield.', 'medium', 2, 2, 90, 'st_edx_4bi1_5', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_039', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which technique makes genetically identical plants quickly?', 'multiple_choice', '["A. Cross-pollination","B. Natural selection","C. Tissue culture","D. Meiosis"]', 'C', 'Small explants divide by mitosis under sterile conditions, producing clones of the parent plant. Therefore the correct answer is C: Tissue culture.', 'hard', 1, 1, 90, 'st_edx_4bi1_5', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_040', 'topic_edx_4bi1_5', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why are biological controls sometimes preferred to pesticides?', 'multiple_choice', '["A. They always remove every pest instantly","B. They cannot affect food webs","C. They never require monitoring","D. They can target a pest with less persistent chemical pollution"]', 'D', 'A carefully assessed natural enemy may reduce pesticide residues, though non-target effects must still be managed. Therefore the correct answer is D: They can target a pest with less persistent chemical pollution.', 'easy', 3, 3, 90, 'st_edx_4bi1_5', 'Explain', 'AO1', 'board_edexcel');
